"use client"

import { User, useAuth } from "@providers/AuthProvider";
import { useState } from "react";
import Image from "next/image";
import { HiOutlineUserCircle } from "react-icons/hi2";
import { useAppContext } from "@providers/AppContext";


export default function UsernameSideCard() {
    const [userInfo, setUserInfo] = useState<User | null>(null);
    const { toggleMainMenu, mainMenuVisible } = useAppContext();

    const [guestUser, setGuestUser] = useState<User>({
        userID: "",
        profilePicture: "/images/profile.png",
        email: "Not Signed In",
        username: "guestuser",
        firstName: "Not",
        lastName: "Signed In",
    });


    return (
        <div 
        className="flex items-center w-[210px] h-[50px] rounded-[16px] my-1 px-1 overflow-hidden cursor-pointer hover:bg-bg-hover transition-all duration-300 ease-in-out">
            <div className="flex items-center gap-2 w-full h-full overflow-hidden">
                <div className="w-auto h-auto rounded-full overflow-hidden flex items-center justify-center gap-4 pr-2 pb-1">
                    {userInfo?.profilePicture ? (
                        <Image src={userInfo?.profilePicture as string} alt="Profile Picture" width={40} height={40} className="rounded-full" />
                    ) : (
                        <HiOutlineUserCircle className="min-w-[30px] min-h-[30px]"/>
                    )}
                </div>
                <div className="flex flex-col truncate">
                    <div className="text-text-primary text-[14px] font-medium capitalize truncate">{userInfo?.firstName || guestUser?.firstName} {userInfo?.lastName || guestUser?.lastName}</div>
                    <div className="text-text-secondary text-[12px] font-medium lowercase truncate">@{userInfo?.username || guestUser?.username}</div>
                </div>
            </div>
        </div>
    );
}